  const quickStart = document.createElement('section'); quickStart.className='module-card'; quickStart.style.marginTop='16px'; quickStart.innerHTML='<div class="flex items-start justify-between gap-3"><div><p class="eyebrow">Configurare ghidată</p><h2 class="text-xl font-black">Creează un modul în 4 pași</h2><p class="muted text-xs mt-1">Alege un punct de pornire, configurează, verifică și publică atunci când ești pregătit.</p></div><select id="module-quick-template" class="field-input" style="max-width:230px"><option value="">Șablon rapid…</option><option value="announcement">Anunț / comunicare</option><option value="request">Cerere / formular</option><option value="approval">Cerere cu aprobare</option><option value="report">Raport / statistici</option><option value="none">De la zero</option></select></div><div class="grid gap-2 sm:grid-cols-4 mt-3"><button type="button" class="button text-left" data-module-step="list"><strong>1. Alege</strong><br><small class="muted">șablonul</small></button><button type="button" class="button text-left" data-module-step="editor"><strong>2. Configurează</strong><br><small class="muted">conținutul</small></button><button type="button" class="button text-left" data-module-step="preview"><strong>3. Verifică</strong><br><small class="muted">web / mobil / Discord</small></button><button type="button" class="button text-left" data-module-step="publication"><strong>4. Publică</strong><br><small class="muted">draft sau live</small></button></div>';
