  const responsesField = document.createElement('div'); responsesField.className='field'; responsesField.innerHTML='<label>Răspunsuri configurabile</label><div class="grid gap-2 sm:grid-cols-2"><input id="module-response-button" class="field-input" placeholder="Răspuns la acțiune"><input id="module-response-success" class="field-input" placeholder="Mesaj de succes"><input id="module-response-error" class="field-input" placeholder="Mesaj de eroare"><input id="module-response-review" class="field-input" placeholder="Mesaj pentru aprobare"></div>'; slashField.after(responsesField);
  const visualField = document.createElement('div'); visualField.className='field'; visualField.innerHTML='<label>Aspect embed Discord</label><div class="grid gap-2 sm:grid-cols-[1fr_90px]"><input id="module-title" class="field-input" placeholder="Titlul afișat în Discord"><input id="module-color" class="field-input h-10 cursor-pointer" type="color" value="#5865f2" title="Culoare embed"></div>'; document.getElementById('module-description')?.parentElement?.after(visualField);
  const buttonsBuilder = document.createElement('div'); buttonsBuilder.className='field'; buttonsBuilder.innerHTML='<div class="flex items-center justify-between gap-2"><label>Buton(e) și acțiuni</label><button type="button" class="button" id="add-module-button">＋ Adaugă buton</button></div><div id="module-buttons-builder" class="module-list"></div>'; $('module-buttons')?.parentElement?.after(buttonsBuilder); $('module-buttons').parentElement.hidden=true;
