  const historyButton = document.createElement('button'); historyButton.id='module-history'; historyButton.type='button'; historyButton.className='button'; historyButton.textContent='🕘 Istoric'; $('module-editor-title')?.parentElement?.parentElement?.appendChild(historyButton);
