  const issueBox = document.createElement('div'); issueBox.id='module-issues-box'; issueBox.className='preview'; issueBox.hidden=true; $('module-issues')?.parentElement?.after(issueBox);
  const status = (text, kind = '') => { const node = $('module-status'); if (node) { node.textContent = text; node.className = `status ${kind}`; } };
  const localDraftKey = () => `panel_module_draft:${$('module-key')?.value.trim() || 'new'}`;
  let draftTimer;
  const saveLocalDraft = () => { clearTimeout(draftTimer); draftTimer=setTimeout(()=>{const item=read();if(!item.module_key||!item.label)return;try{localStorage.setItem(localDraftKey(),JSON.stringify({saved_at:new Date().toISOString(),item}));if($('module-autosave-status'))$('module-autosave-status').textContent='Draft local salvat automat';}catch(_){ }},500); };
  const checkLocalDraft = () => { const node=$('module-restore-local'); if(!node)return; try{const saved=JSON.parse(localStorage.getItem(localDraftKey())||'null');node.hidden=!saved?.item;node.onclick=()=>{if(saved?.item){fill(saved.item);node.hidden=true;status('Draftul local a fost încărcat.','ok');}};}catch(_){node.hidden=true;} };
  const call = async (body) => window.panelRequestJson(endpoint, { method: 'POST', body: JSON.stringify(body), timeoutMs: 12000 });
  const publicationCall = async (body) => { const data = await window.panelRequestJson('manage-panel-modules', { method: 'POST', body: JSON.stringify(body), timeoutMs: 30000 }); if (body.action === 'test' && data.test) setTimeout(() => renderPublicationTestStatus(data.test), 0); return data; };
  const esc = (value) => String(value ?? '').replace(/[&<>'"]/g, (c) => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' }[c]));
