    const publicationIssues=(state.catalog.publications||[]).filter((item)=>String(item.status||'')!=='published'||item.last_error);
    const issueRows=[...state.modules.filter((item)=>moduleState(item)==='draft').map((item)=>({label:`${item.label||item.module_key}: nu are publicație`,module_key:item.module_key})),...publicationIssues.map((item)=>({label:`${item.module_key} · ${item.target}: ${item.last_error||item.status||'nepublicat'}`,module_key:item.module_key,organization_id:item.organization_id,target:item.target,guild_id:item.guild_id}))];
