    issueBox.querySelector('[data-module-health-refresh]')?.addEventListener('click',()=>loadPublications());
    issueBox.querySelector('[data-module-repair-all]')?.addEventListener('click', repairAllIssues);
    issueBox.querySelectorAll('[data-module-repair]').forEach((button)=>button.addEventListener('click',()=>{try{const item=JSON.parse(button.dataset.moduleRepair);$('publication-organization').value=item.organization_id||$('publication-organization').value;renderPublicationSelectors();$('publication-module').value=item.module_key;$('publication-target').value=item.target||'primary';$('publication-guild').value=item.guild_id||'';hydratePublication();publishPublication('repair');}catch(error){status(error.message||'Repararea nu a putut fi pornită.','error');}}));
    $('module-list').innerHTML = filtered.length ? filtered.map((m) => {
      const currentState = moduleState(m);
      const stateLabel = currentState === 'configured' ? '<span class="tag" style="color:#6ee7b7">configurat</span>' : currentState === 'archived' ? '<span class="tag">arhivat</span>' : '<span class="tag" style="color:#fcd34d">draft</span>';
      return `<button type="button" class="module-choice ${m.module_key===state.selected?'active':''}" data-module="${esc(m.module_key)}"><div class="flex items-center justify-between gap-2"><strong>${esc(m.label)}</strong>${stateLabel}</div><small class="muted">${esc(m.description || m.module_key || 'Fără descriere')}</small></button>`;
    }).join('') : `<p class="muted text-xs">${state.modules.length ? 'Niciun modul nu corespunde filtrului ales.' : 'Nu există șabloane. Creează primul modul.'}</p>`;
